  '+': (stack) => {
    const b = pop(stack);
    const a = pop(stack);
    stack.push(a + b);
  },
  '-': (stack) => {
    const b = pop(stack);
    const a = pop(stack);
    stack.push(a - b);
  },
  '*': (stack) => {
    const b = pop(stack);
    const a = pop(stack);
    stack.push(a * b);
  },
  '/': (stack) => {
    const b = pop(stack);
